#!/usr/bin/env python3
"""crispr/screen_analysis_mageck — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "screen_analysis_mageck"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'screen_analysis_mageck', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """MAGeCK CRISPR screen analysis。host_env=PRAXIS-CRISPR-bins。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    count_table = payload.get("count_table_csv") or payload.get("counts")
    library = payload.get("library_csv")
    treatment = payload.get("treatment_samples") or []
    control = payload.get("control_samples") or []
    fastq_list = payload.get("fastq_list")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="mageck_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "mageck", "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not count_table or not _os.path.isfile(count_table):
        return {"ok": False, "error": "需要 count_table_csv", "diagnostics": diagnostics}
    if not treatment or not control:
        return {"ok": False, "error": "需要 treatment_samples + control_samples", "diagnostics": diagnostics}
    _os.makedirs(out_dir, exist_ok=True)
    prefix = _os.path.join(out_dir, "screen")
    t0 = _time.time()
    cmd = ["mageck", "test", "-k", count_table, "-t", ",".join(treatment), "-c", ",".join(control), "-n", prefix]
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 1800)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "mageck 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    gene_tsv = prefix + ".gene_summary.txt"
    n_gene = 0
    if _os.path.isfile(gene_tsv):
        with open(gene_tsv) as fh: n_gene = sum(1 for _ in fh) - 1
    return {"ok": True, "skill_id": SKILL,
            "n_guides": n_gene, "guides_csv": gene_tsv,
            "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "gene_summary": gene_tsv, "n_genes": n_gene}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
